update country_flag_history set label_fr = 'États-Unis (20 étoiles)', label_en = 'United States (20 stars)', notes_fr = 'Le Flag Act de 1818 revient à 13 bandes et fixe une étoile par État, ajoutée le 4 juillet suivant chaque admission : 20 étoiles.', notes_en = 'The 1818 Flag Act went back to 13 stripes and set one star per state, added on the 4 July after each admission: 20 stars.' where id = 2516 and iso_code = 'us';
